package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.steel.*;import dev.industrialtechnology.capacitor.*;
import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.tileentity.*;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.nbt.*;import net.minecraft.entity.item.EntityItem;import net.minecraft.util.AxisAlignedBB;
import net.minecraft.inventory.*;import net.minecraft.item.crafting.CraftingManager;import net.minecraft.entity.player.*;import net.minecraftforge.common.util.*;
@Mod(modid="industrialtech_steel_checks",name="Disposable steel factory checks",version="1",dependencies="required-after:industrialtech")
public final class SteelServerChecks {
    private final List<String> report=new ArrayList<String>();private int ticks,failed;private boolean done,setup;private WorldServer w;private TileSteelFactory he,pipe;private Object battery;private TileEntityChest pipeChest;private long source;
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.steelTest"))FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private void test(String name,Test code){try{code.run();report.add("PASS: "+name);}catch(Throwable e){failed++;report.add("FAIL: "+name+" :: "+e);IndustrialTechnology.log.error(name,e);}}
    interface Test{void run()throws Exception;}
    private TileSteelFactory place(int x,int z){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,70,z,SteelRegistry.factory,3,3);return (TileSteelFactory)w.getTileEntity(x,70,z);}
    private Item hbm(String field)throws Exception{return (Item)Class.forName("com.hbm.items.ModItems").getField(field).get(null);}
    private BlockHolder block(String field)throws Exception{return new BlockHolder((net.minecraft.block.Block)Class.forName("com.hbm.blocks.ModBlocks").getField(field).get(null));}
    private static class BlockHolder{net.minecraft.block.Block b;BlockHolder(net.minecraft.block.Block b){this.b=b;}}
    private void feed(TileSteelFactory t)throws Exception{t.setInventorySlotContents(0,new ItemStack(Items.iron_ingot,32));t.setInventorySlotContents(2,new ItemStack(hbm("powder_coal"),8));}
    private int steel(TileSteelFactory t){int n=0;for(int i=4;i<8;i++)if(t.getStackInSlot(i)!=null)n+=t.getStackInSlot(i).stackSize;return n;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||!MinecraftServer.getServer().isDedicatedServer()||e.phase!=TickEvent.Phase.END)return;
        try{if(++ticks<70)return;w=MinecraftServer.getServer().worldServerForDimension(0);
            if(!setup){setup=true;if(new File("steel-phase1.done").exists()){restart();finish("restart");return;}initial();if(!SteelRegistry.hasHBM){finish("standalone");return;}test("HBM battery and cables create an actual HE route",()->setupPower());test("Thermal itemducts and servos create real ingredient and output routes",()->setupPipes());return;}
            if(ticks==470){test("HBM battery sends HE through three real red cables into working factory",()->{check(he!=null&&he.batches>0&&steel(he)>0,"no steel over HE: "+(he==null?"null":he.status()+" power "+he.getPower()));long left=((Number)battery.getClass().getMethod("getPower").invoke(battery)).longValue();check(left<source,"battery unchanged");check(source-left==he.getPower()+he.batches*50000+he.progress*500,"HE conservation source "+(source-left)+" factory "+he.getPower()+" batches "+he.batches+" progress "+he.progress);});
                test("Real Thermal servo inserts iron and coal dust, extracts only HBM steel into chest",()->{check(pipe!=null&&pipe.batches>0,"factory not fed: "+(pipe==null?"null":pipe.status()));int n=0;for(int i=0;i<pipeChest.getSizeInventory();i++){ItemStack s=pipeChest.getStackInSlot(i);if(s!=null){check(s.getItem()==hbm("ingot_steel"),"servo extracted ingredient");n+=s.stackSize;}}check(n>=16,"no steel in chest "+n);});
                test("World save persists paid partial work, materials and HE for actual JVM restart",()->{TileSteelFactory t=place(160,160);feed(t);t.setPower(100000);for(int i=0;i<37;i++)t.updateEntity();check(t.progress==37&&t.getPower()==81500,"partial work");t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_speed_3")));t.setInventorySlotContents(9,new ItemStack(hbm("upgrade_power_1")));w.saveAllChunks(true,null);Files.write(Paths.get("steel-phase1.done"),Arrays.asList("saved"),StandardCharsets.UTF_8);});finish("initial");}
        }catch(Throwable ex){failed++;report.add("FAIL: harness :: "+ex);IndustrialTechnology.log.error("Steel harness",ex);finish("initial");}}
    private void initial(){
        test("Bank input is green and output red; empty banks still stack 64",()->{int in=SideMode.INPUT.color,out=SideMode.OUTPUT.color;check(((in>>8)&255)>((in>>16)&255),"input not green");check(((out>>16)&255)>((out>>8)&255),"output not red");check(new ItemStack(ModRegistry.capacitorBank).getMaxStackSize()==64,"empty bank stacking");});
        test("Full world meter level 16 is reserved for exact full capacity",()->{w.setBlock(12,70,12,ModRegistry.capacitorBank,3,3);TileCapacitorBank b=(TileCapacitorBank)w.getTileEntity(12,70,12);ItemStack s=new ItemStack(ModRegistry.capacitorBank);NBTTagCompound n=new NBTTagCompound();n.setInteger("BankVersion",1);n.setLong("StoredRF",24999999);s.setTagCompound(n);b.restoreItem(s);b.network().tick(w.getTotalWorldTime());check(b.displayCharge==15,"near-full falsely gold");w.setBlock(16,70,12,ModRegistry.capacitorBank,3,3);b=(TileCapacitorBank)w.getTileEntity(16,70,12);n.setLong("StoredRF",25000000);b.restoreItem(s);b.network().tick(w.getTotalWorldTime());check(b.displayCharge==16,"full not gold");});
        test("Retired solar GUI remains absent",()->{check(IndustrialTechnology.proxy.getServerGuiElement(3,null,w,0,0,0)==null,"solar GUI restored");});
        if(!SteelRegistry.hasHBM){test("Without HBM the mod and inert factory load with no HBM classes",()->{TileSteelFactory t=place(20,20);check(t.getClass()==TileSteelFactory.class&&t.status().equals("HBM required"),"optional load");t.updateEntity();});return;}

        test("Two single-item HBM upgrade slots accept four supported types and reject unrelated upgrades",()->{TileSteelFactory t=place(20,40);SteelContainer c=new SteelContainer(fake().inventory,t);for(String kind:new String[]{"speed","power","effect","overdrive"})for(int tier=1;tier<=3;tier++){ItemStack s=new ItemStack(hbm("upgrade_"+kind+"_"+tier));check(t.isItemValidForSlot(8,s)&&t.isItemValidForSlot(9,s),"supported upgrade rejected");check(((Slot)c.inventorySlots.get(3)).getSlotStackLimit()==1,"slot limit");for(int face=0;face<6;face++)check(!t.canInsertItem(8,s,face)&&!t.canExtractItem(8,s,face),"pipe upgrade access");}for(String rejected:new String[]{"upgrade_fortune_1","upgrade_smelter","upgrade_muffler"})check(!t.isItemValidForSlot(8,new ItemStack(hbm(rejected))),"unrelated upgrade accepted");check(t.getSizeInventory()==10,"exact slot count");});
        test("Real container shift-click installs two upgrades, refuses a third, and removes one without loss",()->{TileSteelFactory t=place(24,40);FakePlayer p=fake();p.inventory.mainInventory[9]=new ItemStack(hbm("upgrade_speed_3"));p.inventory.mainInventory[10]=new ItemStack(hbm("upgrade_power_3"));p.inventory.mainInventory[11]=new ItemStack(hbm("upgrade_effect_3"));SteelContainer c=new SteelContainer(p.inventory,t);check(c.transferStackInSlot(p,5)!=null&&c.transferStackInSlot(p,6)!=null,"install");check(c.transferStackInSlot(p,7)==null&&p.inventory.mainInventory[11]!=null,"third upgrade consumed");check(t.getStackInSlot(8).stackSize==1&&t.getStackInSlot(9).stackSize==1,"too many per slot");check(c.transferStackInSlot(p,3)!=null&&t.getStackInSlot(8)==null,"remove upgrade");});
        test("Actual HBM Speed III produces a 16-steel batch in 25 ticks at 2000 HE/t",()->{TileSteelFactory t=place(28,40);feed(t);t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_speed_3")));t.setPower(100000);for(int i=0;i<24;i++)t.updateEntity();check(t.progress==24&&steel(t)==0&&t.getPower()==52000,"early batch");t.updateEntity();check(t.batches==1&&steel(t)==16&&t.getPower()==50000,"speed effect");});
        test("Actual HBM Power Saving III slows the batch to 130 ticks and consumes only 6500 HE",()->{TileSteelFactory t=place(32,40);feed(t);t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_power_3")));t.setPower(100000);for(int i=0;i<130;i++)t.updateEntity();check(t.batches==1&&steel(t)==16&&t.getPower()==93500,"power effect");});
        test("Actual HBM Effectiveness III consumes one coal dust while preserving 16 iron to 16 steel",()->{TileSteelFactory t=place(36,40);feed(t);t.setInventorySlotContents(2,new ItemStack(hbm("powder_coal")));t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_effect_3")));t.setPower(100000);for(int i=0;i<100;i++)t.updateEntity();check(t.batches==1&&steel(t)==16&&t.getStackInSlot(2)==null&&t.getStackInSlot(0).stackSize==16&&t.getPower()==12500,"effectiveness");});
        test("Actual HBM Overdrive I doubles speed with a higher per-batch HE cost",()->{TileSteelFactory t=place(40,40);feed(t);t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_overdrive_1")));t.setPower(100000);for(int i=0;i<50;i++)t.updateEntity();check(t.batches==1&&steel(t)==16&&t.getPower()==25000,"overdrive effect");});
        test("Swapping upgrades mid-batch cannot discount already-started work; next batch uses new settings",()->{TileSteelFactory t=place(44,40);feed(t);t.setPower(100000);for(int i=0;i<20;i++)t.updateEntity();t.setInventorySlotContents(8,new ItemStack(hbm("upgrade_speed_3")));t.setInventorySlotContents(9,new ItemStack(hbm("upgrade_power_3")));check(t.recipeProfile().ticks==100&&t.recipeProfile().hePerTick==500,"partial recipe changed");for(int i=0;i<80;i++)t.updateEntity();check(t.batches==1&&t.getPower()==50000,"first batch cost changed");check(t.recipeProfile().ticks==55&&t.recipeProfile().hePerTick==1550,"next batch did not change");t.setPower(100000);for(int i=0;i<55;i++)t.updateEntity();check(t.batches==2&&t.getPower()==14750,"next batch accounting");});
        test("Retired buffer contents from old saves drain into visible slots without losing any items",()->{TileSteelFactory t=place(52,40);for(int i=0;i<2;i++)t.setInventorySlotContents(i,new ItemStack(Items.iron_ingot,64));for(int i=2;i<4;i++)t.setInventorySlotContents(i,new ItemStack(hbm("powder_coal"),64));for(int i=4;i<8;i++)t.setInventorySlotContents(i,SteelRegistry.steel(64));NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);t.readFromNBT(n);int iron=0,coal=0,steel=0;for(int step=0;step<5;step++){t.updateEntity();ItemStack a=t.decrStackSize(0,64),b=t.decrStackSize(2,64),c=t.decrStackSize(4,64);if(a!=null)iron+=a.stackSize;if(b!=null)coal+=b.stackSize;if(c!=null)steel+=c.stackSize;}check(iron==128&&coal==128&&steel==256&&t.batches==0,"legacy item loss");SteelContainer container=new SteelContainer(fake().inventory,t);check(container.inventorySlots.size()==41&&SteelContainer.MACHINE_SLOTS==5,"buffer slots still in GUI");for(int i:new int[]{1,3,5,6,7})check(!t.isItemValidForSlot(i,new ItemStack(Items.iron_ingot)),"retired input still enabled");});
        test("Old eight-slot 2.5.0 NBT retains every buffer and finishes its original partial recipe",()->{TileSteelFactory t=place(48,40);feed(t);t.setPower(100000);for(int i=0;i<77;i++)t.updateEntity();NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);n.removeTag("BatchTicks");n.removeTag("BatchHE");n.removeTag("BatchCoal");t.readFromNBT(n);check(t.progress==77&&t.recipeProfile().ticks==100&&t.getStackInSlot(8)==null,"legacy read");for(int i=0;i<23;i++)t.updateEntity();check(t.batches==1&&steel(t)==16&&t.getPower()==50000,"legacy finish");});

        test("Factory is a real HBM HE receiver with overflow-safe remainder contract",()->{TileSteelFactory t=place(24,24);Class<?> receiver=Class.forName("api.hbm.energymk2.IEnergyReceiverMK2");check(receiver.isInstance(t),"not HE");Method transfer=t.getClass().getMethod("transferPower",long.class);check(((Long)transfer.invoke(t,Long.MAX_VALUE))==Long.MAX_VALUE-1000000&&t.getPower()==1000000,"HE remainder/overflow");check(((Long)transfer.invoke(t,1L))==1,"full accepted");});
        test("All six faces accept matching inputs, reject output insertion and expose steel only",()->{TileSteelFactory t=place(28,24);for(int side=0;side<6;side++){check(t.getAccessibleSlotsFromSide(side).length==3,"slots");for(int i=0;i<8;i++){check(t.canInsertItem(i,new ItemStack(Items.iron_ingot),side)==(i==0),"iron slot");check(t.canInsertItem(i,new ItemStack(hbm("powder_coal")),side)==(i==2),"dust slot");check(t.canExtractItem(i,new ItemStack(Items.iron_ingot),side)==(i==4),"extract gate");}check(!t.isItemValidForSlot(2,new ItemStack(Items.coal)),"raw coal accepted");}});
        test("Registered coal dust from Thermal Foundation is accepted without accepting coal items",()->{boolean found=false;for(ItemStack s:net.minecraftforge.oredict.OreDictionary.getOres("dustCoal")){if(Item.itemRegistry.getNameForObject(s.getItem()).toString().startsWith("ThermalFoundation:")){check(TileSteelFactory.coal(s),"Thermal dust rejected");found=true;}}check(found,"No actual Thermal coal dust in test");});
        test("Working and idle furnace artwork follows processing without replacing the tile or contents",()->{TileSteelFactory t=place(98,24);feed(t);t.setPower(100000);t.updateEntity();check(w.getTileEntity(98,70,24)==t&&(w.getBlockMetadata(98,70,24)&8)!=0&&t.progress==1,"active visual replaced tile");t.setPower(0);t.updateEntity();check(w.getTileEntity(98,70,24)==t&&(w.getBlockMetadata(98,70,24)&8)==0&&t.progress==1,"idle visual lost work");});
        test("Exact 100-tick batch consumes 16 iron/4 coal and 50000 HE for 16 genuine HBM steel",()->{TileSteelFactory t=place(32,24);feed(t);t.setPower(100000);for(int i=0;i<99;i++)t.updateEntity();check(steel(t)==0&&t.progress==99&&t.getPower()==50500,"early output");t.updateEntity();check(steel(t)==16&&t.batches==1&&t.getPower()==50000&&t.getStackInSlot(0).stackSize==16&&t.getStackInSlot(2).stackSize==4,"batch accounting");check(t.getStackInSlot(4).getItem()==hbm("ingot_steel"),"fake steel");});
        test("No ingredients or no HE consumes no energy or items",()->{TileSteelFactory t=place(36,24);t.setPower(12345);for(int i=0;i<120;i++)t.updateEntity();check(t.getPower()==12345&&t.progress==0,"idle draw");feed(t);t.setPower(0);for(int i=0;i<120;i++)t.updateEntity();check(t.getStackInSlot(0).stackSize==32&&t.progress==0&&steel(t)==0,"unpowered loss");});
        test("Output backpressure and power shortage pause already-paid progress without loss",()->{TileSteelFactory t=place(40,24);feed(t);t.setPower(100000);for(int i=0;i<50;i++)t.updateEntity();t.setInventorySlotContents(4,SteelRegistry.steel(64));for(int i=0;i<130;i++)t.updateEntity();check(t.progress==50&&t.getPower()==75000,"blocked used HE");t.setInventorySlotContents(4,null);t.setPower(499);t.updateEntity();check(t.progress==50&&t.getPower()==499,"low power progressed");t.setPower(25000);for(int i=0;i<50;i++)t.updateEntity();check(t.batches==1&&t.getPower()==0&&t.getStackInSlot(4).stackSize==16,"resume batch");});
        test("NBT round-trip preserves exact partial work, HE and all ordinary item stacks",()->{TileSteelFactory t=place(44,24);feed(t);t.setPower(123456);for(int i=0;i<19;i++)t.updateEntity();NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);TileSteelFactory copy=new TileSteelFactory();copy.readFromNBT(n);check(copy.getPower()==113956&&copy.progress==19&&copy.getStackInSlot(0).stackSize==32,"round trip");});
        test("Survival factory recipe requires 4 tungsten blocks, 2 HBM motors, circuits and expensive core",()->{InventoryCrafting g=new InventoryCrafting(new Container(){public boolean canInteractWith(EntityPlayer p){return true;}},3,3);ItemStack[] a={new ItemStack(block("block_tungsten").b),new ItemStack(hbm("motor")),new ItemStack(block("block_tungsten").b),new ItemStack(ModRegistry.circuit),new ItemStack(SteelRegistry.core),new ItemStack(ModRegistry.circuit),new ItemStack(block("block_tungsten").b),new ItemStack(hbm("motor")),new ItemStack(block("block_tungsten").b)};for(int i=0;i<9;i++)g.setInventorySlotContents(i,a[i]);ItemStack out=CraftingManager.getInstance().findMatchingRecipe(g,w);check(out!=null&&out.getItem()==Item.getItemFromBlock(SteelRegistry.factory),"factory recipe");for(int i=0;i<9;i++)g.setInventorySlotContents(i,new ItemStack(i==4?Blocks.diamond_block:block("block_steel").b));out=CraftingManager.getInstance().findMatchingRecipe(g,w);check(out!=null&&out.getItem()==SteelRegistry.core,"core recipe");});
        test("Shift-click routes ingredients into correct slots and outputs into player inventory",()->{TileSteelFactory t=place(48,24);FakePlayer p=fake();p.setPosition(48,70,25);p.inventory.mainInventory[9]=new ItemStack(Items.iron_ingot,32);p.inventory.mainInventory[10]=new ItemStack(hbm("powder_coal"),8);SteelContainer c=new SteelContainer(p.inventory,t);c.transferStackInSlot(p,5);c.transferStackInSlot(p,6);check(t.getStackInSlot(0).stackSize==32&&t.getStackInSlot(2).stackSize==8,"shift input");t.setInventorySlotContents(4,SteelRegistry.steel(16));c.transferStackInSlot(p,2);check(t.getStackInSlot(4)==null,"shift output");});
        test("Container split-word HE synchronization preserves values above 32767 and updates progress",()->{SteelContainer c=new SteelContainer(fake().inventory,place(52,24));c.updateProgressBar(0,(short)(987654&65535));c.updateProgressBar(1,(short)(987654>>>16));c.updateProgressBar(2,83);check(c.shownPower==987654&&c.shownProgress==83,"sync words");});
        test("AE2's real inventory adaptor inserts and extracts through every factory face",()->{if(!Loader.isModLoaded("appliedenergistics2"))throw new AssertionError("AE2 missing from test");Class<?> a=Class.forName("appeng.util.InventoryAdaptor"),dest=Class.forName("appeng.util.inv.IInventoryDestination");Method get=a.getMethod("getAdaptor",Object.class,ForgeDirection.class),add=a.getMethod("addItems",ItemStack.class),sim=a.getMethod("simulateAdd",ItemStack.class),remove=a.getMethod("removeItems",int.class,ItemStack.class,dest);for(ForgeDirection side:ForgeDirection.VALID_DIRECTIONS){TileSteelFactory t=place(60+side.ordinal()*4,24);Object adapter=get.invoke(null,t,side);check(adapter!=null,"no AE2 adapter");check(sim.invoke(adapter,new ItemStack(Items.iron_ingot,16))==null&&t.getStackInSlot(0)==null,"simulation changed inventory");check(add.invoke(adapter,new ItemStack(Items.iron_ingot,16))==null,"iron rejected");check(add.invoke(adapter,new ItemStack(hbm("powder_coal"),4))==null,"coal rejected");check(add.invoke(adapter,SteelRegistry.steel(1))!=null,"accepted output injection");check(remove.invoke(adapter,16,new ItemStack(Items.iron_ingot),null)==null,"AE2 extracted input");t.setInventorySlotContents(4,SteelRegistry.steel(16));ItemStack got=(ItemStack)remove.invoke(adapter,16,SteelRegistry.steel(1),null);check(got!=null&&got.stackSize==16&&t.getStackInSlot(4)==null,"AE2 output failed");}});
        test("Breaking factory drops each buffered material once",()->{TileSteelFactory t=place(92,24);feed(t);t.setInventorySlotContents(4,SteelRegistry.steel(16));w.setBlockToAir(92,70,24);List<EntityItem> items=w.getEntitiesWithinAABB(EntityItem.class,AxisAlignedBB.getBoundingBox(91,69,23,94,72,26));int n=0;for(EntityItem e:items)n+=e.getEntityItem().stackSize;check(n==56,"drops "+n);});
    }
    private FakePlayer fake(){FakePlayer p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"SteelTest")){@Override public void sendPlayerAbilities(){}};p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);return p;}
    private void setupPower()throws Exception{he=place(100,100);feed(he);w.setBlock(96,70,100,block("machine_battery").b,0,3);battery=w.getTileEntity(96,70,100);battery.getClass().getField("redLow").setShort(battery,(short)2);battery.getClass().getField("redHigh").setShort(battery,(short)2);source=200000; battery.getClass().getMethod("setPower",long.class).invoke(battery,source);for(int i=97;i<100;i++)w.setBlock(i,70,100,block("red_cable").b,0,3);}
    private void duct(int x,int z)throws Exception{FakePlayer p=fake();w.setBlock(x,69,z,Blocks.stone);Object d=Class.forName("cofh.thermaldynamics.duct.TDDucts").getField("itemFast").get(null);ItemStack item=(ItemStack)d.getClass().getField("itemStack").get(d);check(item.copy().tryPlaceItemIntoWorld(p,w,x,69,z,1,.5F,1,.5F),"duct placement");}
    private void servo(int x,int z,int face)throws Exception{Object tile=w.getTileEntity(x,70,z);Class<?> base=Class.forName("cofh.thermaldynamics.block.TileTDBase"),attachment=Class.forName("cofh.thermaldynamics.block.Attachment"),type=Class.forName("cofh.thermaldynamics.duct.attachments.servo.ServoItem"),control=Class.forName("cofh.api.tileentity.IRedstoneControl$ControlMode");Object servo=type.getConstructor(base,byte.class,int.class).newInstance(tile,(byte)face,4);check((Boolean)base.getMethod("addAttachment",attachment).invoke(tile,servo),"servo attachment");type.getMethod("setControl",control).invoke(servo,control.getField("DISABLED").get(null));base.getMethod("onNeighborBlockChange").invoke(tile);}
    private void setupPipes()throws Exception{check(Loader.isModLoaded("ThermalDynamics"),"TD missing");pipe=place(120,120);pipe.setPower(200000);w.setBlock(116,70,120,Blocks.chest,0,3);TileEntityChest input=(TileEntityChest)w.getTileEntity(116,70,120);input.setInventorySlotContents(0,new ItemStack(Items.iron_ingot,32));input.setInventorySlotContents(1,new ItemStack(hbm("powder_coal"),8));for(int x=117;x<120;x++)duct(x,120);servo(117,120,4);for(int x=121;x<=123;x++)duct(x,120);w.setBlock(124,70,120,Blocks.chest,0,3);pipeChest=(TileEntityChest)w.getTileEntity(124,70,120);servo(121,120,4);}
    private void restart(){test("Real JVM restart preserves both upgrades and locked batch, then applies new upgrade profile",()->{w.getChunkFromChunkCoords(10,10);TileSteelFactory t=(TileSteelFactory)w.getTileEntity(160,70,160);check(t!=null&&t.recipeProfile().ticks==100&&t.recipeProfile().hePerTick==500&&t.getStackInSlot(8).getItem()==hbm("upgrade_speed_3")&&t.getStackInSlot(9).getItem()==hbm("upgrade_power_1")&&t.progress==37&&t.getPower()==81500&&t.getStackInSlot(0).stackSize==32&&t.batches==0,"restore");for(int i=0;i<63;i++)t.updateEntity();check(t.progress==0&&t.batches==1&&t.getPower()==50000&&steel(t)==16,"resume accounting");check(t.recipeProfile().ticks==35&&t.recipeProfile().hePerTick==1850,"new saved upgrade profile");});}
    private void finish(String phase){if(done)return;done=true;try{report.add("Failed: "+failed);Files.write(Paths.get("steel-"+phase+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}
}
